IDENTITY_BOUND_COMPLETION_GATE = "IDENTITY-BOUND BODY/UNSEEN OUTFIT — BEFORE DESIGN: Lock each person's own anchored identity, age and gender presentation before choosing body or clothes. Never change a man/boy into a woman/girl or vice versa. Hair length, crop, screenshot text, another person and random design candidates cannot decide gender/anatomy. For an unseen masculine torso use a natural male chest with a flat garment front, no invented breasts/bust shaping, cleavage or hourglass hips. Uncertain presentation uses a modest neutral contour. Preserve genuine visible contours. For wholly unseen masculine/uncertain clothing choose separate trousers, jeans or tailored shorts, one simple separate T-shirt/shirt/knit/sweatshirt if the top is unseen, and flat neutral sneakers/canvas shoes/loafers/casual lace-up shoes if both shoes are unseen. Ignore random skirts/dresses/bodysuits/feminine blouses, ballet flats/Mary Janes, bows, ankle straps and heels. Colors/patterns may vary within these categories. Clearly feminine people retain age-appropriate completion freedom, without exaggerated anatomy. Visible source clothes/shoes/contours ALWAYS win regardless of gender, including a man actually wearing a skirt or heels. Defaults affect missing evidence only. Apply independently per person; never borrow anatomy or clothing."

FINAL_IDENTITY_COMPLETION_AUDIT = 'FINAL IDENTITY COMPLETION AUDIT — AFTER ANCHORS: Recheck IDENTITY-BOUND BODY/UNSEEN OUTFIT for each anchored identity/age/gender, including modest masculine/uncertain unseen anatomy and separate bottoms/flat shoes. Genuine visible contours, clothes and shoes always override defaults. Keep all other fidelity rules.'

def build_my3d_direct_prompt(
    wardrobe_profile: str | None = None,
    wardrobe_palette: str | None = None,
    *,
    upper_garment_profile: str | None = None,
    footwear_profile: str | None = None,
    source_context: str = "general",
) -> str:
    """Same complete policy for general/close; parameters affect unseen regions only."""
    wardrobe = WARDROBE_COMPLETIONS.get(wardrobe_profile or "", WARDROBE_COMPLETIONS["shorts"])
    palette = WARDROBE_PALETTES.get(wardrobe_palette or "", WARDROBE_PALETTES["pastel"])
    colors = UNSEEN_COLOR_DIRECTIONS.get(wardrobe_palette or "", UNSEEN_COLOR_DIRECTIONS["pastel"])
    upper = UPPER_GARMENT_COMPLETIONS.get(upper_garment_profile or "", "a coordinated upper-garment design")
    footwear = FOOTWEAR_STYLES.get(footwear_profile or "", FOOTWEAR_COMPLETIONS.get(wardrobe_profile or "", FOOTWEAR_COMPLETIONS["shorts"]))
    return "\n\n".join([
        SOURCE_ORIENTATION_OWNERSHIP_POLICY,
        MATERIAL_COLOR_POLICY,
        POSE_AXIS_PROOF_GATE,
        FIGURE_PROPORTION_POLICY,
        CLOSE_PORTRAIT_CLOTHING_EVIDENCE_GATE,
        UPPER_LAYER_EVIDENCE_GATE,
        LOWER_BODY_SOURCE_EVIDENCE_GATE,
        IDENTITY_BOUND_COMPLETION_GATE,
        SINGLE_PERSON_PROMPT_TEMPLATE.format(
            wardrobe=wardrobe, palette=palette, colors=colors, upper=upper, footwear=footwear,
        ),
        FINAL_POSE_AXIS_AUDIT,
        FINAL_CLOTHING_EVIDENCE_AUDIT,
        FINAL_UPPER_LAYER_AUDIT,
        FINAL_LOWER_BODY_FIDELITY_AUDIT,
        FINAL_IDENTITY_COMPLETION_AUDIT,
    ])


PAIR_ANCHOR_ARM_OWNERSHIP_AUDIT = 'FINAL CAST/CONTACT AUDIT — AFTER ANCHORS: A=Image 2, B=Image 3 retain their bound Image 1 identity/body/clothes/pose and same-hand items/grips; exclude others. Enforce both CONTACT ELIGIBILITY branches: preserve existing contact; separated figures move closer only as intact units for body-surface contact, without new gestures. Trace exactly four owned arm-hand chains, one endpoint each including hidden hands. Keep inner arms and normal fingers; no extra/detached/fused palm, branched wrist or limb intersection.'

PAIR_CAST_PRIORITY_GATE = 'PAIR CAST PRIORITY: Image 2 and Image 3 are the exclusive identity roster. Match each to its bound face in Image 1 before reading body/clothing/action evidence. Image 1 may contain unaccepted interaction partners or larger faceless bodies: exclude them completely, even when they make the scene look like a conventional couple. Never replace either anchored person or infer a male/female partner stereotype. Preserve both anchored identities and gender presentations.'

PAIR_CONTACT_ELIGIBILITY_GATE = "CONTACT ELIGIBILITY — SOURCE POSE FIRST: Decide whether the two accepted people already touch in Image 1. ALREADY CONNECTED: Preserve the original contact type, participating anatomical sides, body surfaces, arm/hand arrangement and same-hand belongings/grips. Keep source-supported hand holding, linked arms, shoulder/waist support or leaning only when they already exist; never replace the original connection with a new gesture or add a second connection. If standing conversion is needed, adapt only the positions/heights necessary to retain that same connection. SEPARATED: Preserve each person's supported pose, all original shoulder-elbow-wrist-hand chains, hand heights, gestures, held items and grips. Move the two complete figures closer as units until adjacent shoulder, upper-arm, elbow or torso surfaces naturally touch; choose a surface reachable in their retained poses. Adjust placement and spacing only, not individual joints or gestures. Do not invent hand holding, linked arms, a hand on a shoulder/back, a waist embrace, handshake, fist bump or stacked hands. Do not bend, extend, cross, raise or lower an arm to make contact, release a grip, or add a connecting hand. Do not invent a head/torso lean to bridge the gap. For both branches, retain exactly four owned arm-hand chains, one endpoint per arm including occluded hands; no detached/extra/fused hand, branched wrist, crossed ownership, body penetration or fused clothing. Contact joins two distinct figures without merging their anatomy or outfits."

PAIR_AMBIGUOUS_HAND_POLICY = 'PAIR AMBIGUOUS-HAND SAFETY — HIGHEST PRIORITY: Blur, compression, tiny or occluded fingers do not prove a gesture, grip, object or digit count. Preserve every reliable shoulder-elbow-wrist chain and hand height for both people; an unclear hand must not drift or become a new connection. At its supported wrist, complete one anatomically natural relaxed closed-hand silhouette, four gently folded fingers and one thumb. Use a fitting grip only for a clearly source-supported held item or existing contact. Do not guess signs, pointing, splayed fingertips, objects or contact hands; do not hide an arm end, draw a stump or imitate blur.'

PAIR_CONTACT_PREFERENCES = {'arm_contact': 'CONTACT PLAN: Apply CONTACT ELIGIBILITY exactly; keep original connections, otherwise use pose-preserving body-surface placement only.'}


def choose_my3d_pair_contact_preference() -> str:
    """Keep the existing route parameter while disabling randomized gestures."""
    return "arm_contact"


